context:
New read-only API in Continuum Rust/rusqlite. Existing Store::open initialization/WAL+FULL/BEGINIMMEDIATE writer path is unchanged. All public read methods use store.connection; none ends the read transaction. Store has Connection only, dropped normally. Mutation methods start their own immediate transactions and are documented unsupported on a read-only handle; SQLite READ_ONLY flags forbid writing and nested transaction attempts fail. New constructor:
    /// Opens only an existing supported database, without initialization or a
    /// writer reservation. Reads share a snapshot pinned during validation until
    /// this handle is dropped; reopen to observe later commits. SQLite may need
    /// WAL shared-memory bookkeeping access. No writable fallback is attempted.
    /// Mutation/backup methods on this pinned read-only handle are unsupported.
    pub fn open_existing_read_only(path: impl AsRef<Path>) -> Result<Self> {
        let connection = Connection::open_with_flags(path, OpenFlags::SQLITE_OPEN_READ_ONLY)?;
        connection.busy_timeout(Duration::from_secs(5))?;
        connection.execute_batch("BEGIN DEFERRED")?;
        // Keep validation and all subsequent reads in one read transaction.
        let application: i64 =
            connection.pragma_query_value(None, "application_id", |r| r.get(0))?;
        let version: i64 = connection.pragma_query_value(None, "user_version", |r| r.get(0))?;
        if application != APPLICATION_ID || version != DATABASE_VERSION {
            return Err(Error::UnsupportedDatabase(format!(
                "application={application}, version={version}"
            )));
        }
        Ok(Self { connection })
    }


